/**
 * Filters an array based on a provided predicate function.
 *
 * @param {Array} arr The array to filter.
 * @param {Function} predicate The function to test each element.  Should return a boolean.
 * @returns {Array} A new array containing only elements that satisfy the predicate.
 */
export function customFilter(arr, predicate) {
  const result = [];
  for (const element of arr) {
    if (predicate(element)) {
      result.push(element);
    }
  }
  return result;
}
